import fs from 'node:fs';
import path from 'node:path';
import process from 'node:process';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const sourcePath = path.join(root, 'internal', 'api', 'contract.json');
const outputPath = path.join(root, 'frontend', 'src', 'generated', 'api-contract.ts');
const checkOnly = process.argv.includes('--check');
const contract = JSON.parse(fs.readFileSync(sourcePath, 'utf8'));

const lines = [
  '/* eslint-disable */',
  '// This file is generated by scripts/generate-contract.mjs. Do not edit it directly.',
  '',
  `export const DEVLAN_PROTOCOL_VERSION = ${contract.protocolVersion} as const;`,
  '',
];

const aliases = {
  ProjectKind: "'linked' | 'parked'",
  ProjectMode: "'auto' | 'php' | 'dev' | 'static'",
  ProjectFramework: "'laravel' | 'symfony' | 'generic' | 'vite' | 'astro' | 'nextjs' | 'nuxt' | 'sveltekit' | 'static' | 'unknown'",
  ProjectStatus: "'stopped' | 'starting' | 'ready' | 'degraded' | 'error'",
  LocalDevState: "'active' | 'starting' | 'stopped' | 'available'",
  LanPreviewState: "'ready' | 'paused'",
  MetricsRange: "'15m' | '1h' | '24h' | '7d'",
};
for (const [name, type] of Object.entries(aliases)) {
  lines.push(`export type ${name} = ${type};`);
}
lines.push('');

for (const [name, spec] of Object.entries(contract.types)) {
  lines.push(`export interface ${name} {`);
  for (const [field, definition] of Object.entries(spec.fields)) {
    lines.push(`  ${field}${definition.required ? '' : '?'}: ${definition.type};`);
  }
  lines.push('}', '');
}

lines.push('export const DEVLAN_API_CONTRACT = ' + JSON.stringify({
  protocolVersion: contract.protocolVersion,
  operations: contract.operations,
}, null, 2) + ' as const;', '');

const output = `${lines.join('\n')}\n`;
if (checkOnly) {
  const current = fs.existsSync(outputPath) ? fs.readFileSync(outputPath, 'utf8') : '';
  if (current !== output) {
    console.error(`Contrato TypeScript desatualizado: ${path.relative(root, outputPath)}`);
    process.exit(1);
  }
} else {
  fs.mkdirSync(path.dirname(outputPath), { recursive: true });
  fs.writeFileSync(outputPath, output);
}
